const source = 'Oxane Partners assessment-aligned public reports';

const card = (id, subcategory, difficulty, question, answer, explanation, formula = '', cardType = 'concept', trick = '') => ({
  id: `oxane_apt_${id}`,
  category: 'Aptitude',
  subcategory,
  difficulty,
  card_type: cardType,
  question,
  answer,
  explanation,
  source,
  tags: ['Oxane Partners', 'Assessment aligned', subcategory],
  ...(formula ? { formula } : {}),
  ...(trick ? { trick } : {}),
});

const topic = (prefix, subcategory, items) => items.map((item, index) => {
  const [difficulty, question, answer, explanation, formula = ''] = item;
  return card(`${prefix}_${String(index + 1).padStart(3, '0')}`, subcategory, difficulty, question, answer, explanation, formula);
});

const shortcut = (id, title, answer, explanation) => card(
  `shortcut_${String(id).padStart(3, '0')}`,
  'Shortcuts',
  'Easy',
  title,
  answer,
  explanation,
  '',
  'shortcut',
);

const quantitativeFoundations = topic('quant', 'Quantitative Foundations', [
  ['Medium', 'Revenue is 25% above budget and then falls 12% from that actual level. Where does it finish relative to budget?', '10% above budget.', 'Use successive multipliers: 1.25 x 0.88 = 1.10.', 'Final / Budget = 1.25 x 0.88 = 1.10'],
  ['Hard', 'A value rises by x% and then falls by x%, leaving it 9% below its starting value. Find x.', '30%.', 'Equal percentage increases and decreases create a net loss of x squared divided by 100 percent.', '1 - x^2/10,000 = 0.91, so x = 30'],
  ['Medium', 'A salary rises by 20%, then by 10%, and then falls by 25%. What is the net change?', 'A 1% decrease.', 'The combined multiplier is 1.20 x 1.10 x 0.75 = 0.99.', 'Net multiplier = 1.20 x 1.10 x 0.75 = 0.99'],
  ['Hard', 'Two amounts are in the ratio 3:5. After 40 is transferred from the larger amount to the smaller, the ratio becomes 5:7. Find their original total.', '960.', 'Let the amounts be 3k and 5k. Solving (3k + 40)/(5k - 40) = 5/7 gives k = 120.', '7(3k + 40) = 5(5k - 40)'],
  ['Medium', 'Two numbers are in the ratio 7:11 and sum to 324. Find them.', '126 and 198.', 'There are 18 parts; each part is 18.', 'Numbers = 7 x 18 and 11 x 18'],
  ['Medium', 'A product is marked 30% above cost and sold at a 10% discount. What is the profit percentage?', '17%.', 'Assume cost is 100, so marked price is 130 and selling price is 117.', 'Selling price = 100 x 1.30 x 0.90'],
  ['Medium', 'A product has a 25% markup on cost. What is its margin on selling price?', '20%.', 'If cost is 100, selling price is 125 and profit is 25.', 'Margin = Profit / Selling price = 25 / 125'],
  ['Medium', 'The average of eight observations is reported as 24, but a value of 18 was entered as 81. What is the corrected average?', '16.125.', 'The reported total is 192. Replacing 81 with 18 reduces it to 129, and 129/8 = 16.125.', 'Corrected mean = (8 x 24 - 81 + 18) / 8'],
  ['Medium', 'A portfolio buys 60 units at 80 and 40 units at 110. What is the weighted average price?', '92.', 'Weight each price by its number of units.', 'Weighted average = (60 x 80 + 40 x 110) / 100'],
  ['Medium', 'A shopkeeper gains 20% after giving a 10% discount. What is the marked price as a percentage of cost?', '133.33% of cost.', 'The selling price is 120% of cost and equals 90% of marked price.', 'Marked price = 120 / 0.90 = 133.33'],
  ['Medium', 'Simple interest for three years at 8% per year is 1,920. Find the principal.', '8,000.', 'Rearrange the simple-interest formula: principal equals interest divided by rate and time.', 'P = 1,920 / (0.08 x 3) = 8,000'],
  ['Medium', 'What is the difference between simple and compound interest on 10,000 at 10% for two years?', '100.', 'Both methods earn 1,000 in year one. Compound interest earns an additional 10% on that first-year interest in year two, creating the 100 difference.', 'CI - SI = P x (R/100)^2'],
  ['Medium', 'What is the effective annual rate for a 12% nominal rate compounded quarterly?', '12.55% approximately.', 'The quarterly rate is 3%, applied four times. Compounding each period produces a realized annual rate above the stated 12% nominal rate.', 'EAR = (1 + 12%/4)^4 - 1'],
  ['Medium', 'Two positive integers have HCF 12 and LCM 720. If one integer is 144, find the other.', '60.', 'For two positive integers, their product equals HCF times LCM.', 'Other integer = (12 x 720) / 144 = 60'],
  ['Medium', 'Is 4,572 divisible by 3 and by 9?', 'It is divisible by both 3 and 9.', 'Its digit sum is 4 + 5 + 7 + 2 = 18, and 18 is divisible by both 3 and 9.', 'Digit-sum test: 18 is divisible by 3 and 9'],
  ['Medium', 'What is the remainder when 2,347 is divided by 7?', '2.', 'The largest multiple of 7 not exceeding 2,347 is 7x335 = 2,345. Subtracting it from the dividend leaves the required remainder of 2.', 'Remainder = Dividend - Divisor x Quotient'],
  ['Medium', 'Solve: 3x + 2y = 18 and x - y = 1.', 'x = 4, y = 3.', 'Substitute x = y + 1 into the first equation.', 'Use substitution or elimination'],
  ['Medium', 'A ratio changes from 4:7 to 5:8 after adding the same amount to both terms. What amount was added?', '1.', 'Solve 8(4 + x) = 5(7 + x): 32 + 8x = 35 + 5x, so x = 1.', '8(4 + x) = 5(7 + x)'],
  ['Medium', 'A price is reduced by 20%. By what percentage must the reduced price rise to return to the original price?', '25%.', 'A price of 100 falls to 80. Recovering 20 on a base of 80 requires 20/80 = 25%.', 'Required increase = (100 - 80) / 80 x 100'],
  ['Medium', 'Forty percent of A equals 60% of B. If A + B = 250, find A and B.', 'A = 150 and B = 100.', 'From 0.4A = 0.6B, A:B = 3:2. Five parts total 250, so each part is 50.', '0.4A = 0.6B, so A:B = 3:2'],
]);

const speedWorkAges = topic('speed', 'Speed, Work and Ages', [
  ['Medium', 'A train increases speed from 54 km/h to 72 km/h over a 300-metre section. How much travel time is saved?', '5 seconds.', 'The speeds are 15 m/s and 20 m/s, so the times are 20 seconds and 15 seconds.', 'Time saved = 300/15 - 300/20 = 5 seconds'],
  ['Medium', 'A 100-metre bus travelling at 20 m/s crosses a bridge in 15 seconds. Find the bridge length.', '200 metres.', 'The bus covers its own length plus the bridge length: 20 x 15 = 300 metres in total.', 'Bridge length = Speed x Time - Bus length'],
  ['Hard', 'Two vehicles are 180 km apart. A starts toward B at 60 km/h; B starts 30 minutes later toward A at 40 km/h. How long after A starts do they meet?', '2 hours.', 'A covers 30 km before B starts, leaving 150 km. Their closing speed is then 100 km/h, so they need another 1.5 hours.', 'Total time = 0.5 + (180 - 60 x 0.5)/(60 + 40)'],
  ['Medium', 'A 180-metre train travels at 54 km/h. How long does it take to pass a pole?', '12 seconds.', 'Convert 54 km/h to 15 m/s. To clear a point object, the train must travel exactly its own 180-metre length, requiring 180/15 seconds.', 'Time = 180 / 15'],
  ['Medium', 'Two trains of 120 metres and 180 metres travel toward each other at 36 km/h and 54 km/h. Find crossing time.', '12 seconds.', 'Total distance is 300 metres and relative speed is 25 m/s.', 'Time = (120 + 180) / ((36 + 54) x 5/18)'],
  ['Medium', 'Two trains travel in the same direction at 72 km/h and 54 km/h. What is relative speed?', '18 km/h.', 'The faster train gains only the difference between their speeds because both move in the same direction. It therefore closes the gap at 18 km/h, or 5 m/s.', 'Relative speed = 72 - 54'],
  ['Medium', 'A boat moves at 15 km/h in still water and the stream moves at 3 km/h. Find downstream and upstream speeds.', '18 km/h downstream; 12 km/h upstream.', 'Add the stream speed downstream and subtract it upstream.', 'Downstream = Boat + Stream; Upstream = Boat - Stream'],
  ['Medium', 'A car travels 120 km at 60 km/h and returns at 40 km/h. Find average speed.', '48 km/h.', 'For equal distances, use total distance divided by total time.', 'Average speed = 2ab / (a + b)'],
  ['Medium', 'Two people 150 km apart travel toward each other at 40 km/h and 35 km/h. When do they meet?', 'After 2 hours.', 'Because they move toward each other, their distances covered add and the gap closes at 75 km/h. Dividing 150 km by that combined speed gives two hours.', 'Time = 150 / (40 + 35)'],
  ['Hard', 'A can complete a job in 12 days and B in 18 days. They work together for three days, after which A leaves. How long does the whole job take?', '13.5 days.', 'Together they complete 3(1/12 + 1/18) = 5/12. B completes the remaining 7/12 in 10.5 days.', 'Total time = 3 + (7/12)/(1/18) = 13.5 days'],
  ['Medium', 'A is twice as efficient as B. If B takes 18 days, how long does A take?', '9 days.', 'Twice the efficiency means completing twice as much work per day. For the same fixed job, required time therefore halves from B’s 18 days to A’s nine days.', 'Time_A = Time_B / 2'],
  ['Medium', 'Three workers complete a job in 12, 15, and 20 days. Find their joint time.', '5 days.', 'Their daily rates sum to 1/12 + 1/15 + 1/20.', 'Joint rate = 1/12 + 1/15 + 1/20'],
  ['Medium', 'A pipe fills a tank in 8 hours and another empties it in 12 hours. Find net filling time.', '24 hours.', 'The inlet adds 1/8 of the tank per hour while the outlet removes 1/12. Their net rate is 1/24 of the tank per hour, so filling takes 24 hours.', 'Net rate = Fill rate - Emptying rate'],
  ['Medium', 'A pipe fills a tank in 6 hours. A leak empties it in 18 hours. How long will filling take with the leak open?', '9 hours.', 'The inlet adds 1/6 of a tank each hour and the leak removes 1/18. The surviving rate is 1/9, so the tank fills in nine hours.', 'Net time = 1 / (1/6 - 1/18)'],
  ['Medium', 'A completes 60% of a job in nine days, while B completes 40% of the same job in eight days. How long would they take working together?', '60/7 days, or about 8.57 days.', 'A would take 15 days for the full job and B would take 20 days. Their combined rate is 1/15 + 1/20 = 7/60.', 'Joint time = 1 / (1/15 + 1/20) = 60/7'],
  ['Medium', 'A father is three times as old as his son. Their ages total 48. Find both ages.', 'Father 36; son 12.', 'Let the son’s age be x and the father’s age be 3x. Their total gives 4x = 48, so x = 12 and the father is 36.', 'x + 3x = 48'],
  ['Medium', 'Five years from now, A will be twice B’s age. Their current ages total 50. Find current ages.', 'A 35; B 15.', 'Use current ages x and y with x + y = 50 and x + 5 = 2(y + 5). Solving gives y = 15 and x = 35.', 'x + y = 50; x + 5 = 2y + 10'],
  ['Medium', 'Mix a 20% solution and a 50% solution to create a 30% solution. Find the ratio.', 'Use the 20% and 50% solutions in a 2:1 ratio.', 'The low solution is ten points below the target and the high solution is twenty points above it. Twice as much low solution balances one part high solution.', 'Low:High = (50 - 30):(30 - 20)'],
  ['Medium', 'A partner invests 60,000 for 8 months and another invests 40,000 for 12 months. Divide profit.', 'Divide the profit equally, in a 1:1 ratio.', 'Profit sharing follows capital multiplied by time. Both weighted investments equal 480,000, so neither partner has a larger time-adjusted contribution.', 'Profit ratio = 60,000x8 : 40,000x12 = 1:1'],
  ['Hard', 'A cyclist covers one-third of a journey at 12 km/h and the remaining two-thirds at 18 km/h. Find the average speed for the whole journey.', '108/7 km/h, or approximately 15.43 km/h.', 'For total distance D, time is D/36 + D/27 = 7D/108. Dividing D by that time gives 108/7 km/h.', 'Average speed = D / (D/36 + D/27) = 108/7'],
]);

const probabilityStatistics = topic('probability', 'Probability and Statistics', [
  ['Medium', 'Three fair coins are tossed. Given that at least one head appears, what is the probability of getting exactly two heads?', '3/7.', 'Excluding TTT leaves seven equally likely outcomes; HHT, HTH, and THH have exactly two heads.', 'P(exactly two heads | at least one head) = 3/7'],
  ['Medium', 'Two fair dice are rolled. Given that at least one die shows 3, what is the probability that the total is 8?', '2/11.', 'There are 11 ordered outcomes with at least one 3. Only (3,5) and (5,3) total 8.', 'Conditional probability = 2 favorable outcomes / 11 conditioned outcomes'],
  ['Medium', 'What is the probability of drawing two aces without replacement?', '1/221, or approximately 0.452%.', 'The first draw has probability 4/52. Without replacement, only three aces remain among 51 cards for the second draw, so the dependent probabilities multiply.', 'P = (4/52) x (3/51)'],
  ['Medium', 'Events A and B are independent with P(A) = 0.4 and P(B) = 0.5. What is the probability that at least one occurs?', '0.7, or 70%.', 'Independence gives P(A and B) = 0.4 x 0.5 = 0.2. Apply inclusion-exclusion.', 'P(A or B) = 0.4 + 0.5 - 0.2 = 0.7'],
  ['Medium', 'A test is positive for 5% of healthy borrowers and 80% of defaulting borrowers. Why is conditional probability needed?', 'Because the base default rate changes the meaning of a positive test.', 'The probability of default given a positive result is not the same as the probability of a positive result given default.', 'P(Default | Positive) differs from P(Positive | Default)'],
  ['Hard', 'A borrower has a 3% prior default probability. A warning signal appears for 80% of defaulting borrowers and 5% of non-defaulting borrowers. Given a warning, what is the probability of default?', 'Approximately 33.1%.', 'Bayes’ theorem gives 0.03x0.80 divided by [0.03x0.80 + 0.97x0.05] = 0.331.', 'P(Default | Warning) = 0.024 / (0.024 + 0.0485)'],
  ['Medium', 'An investment pays 100 with probability 0.6 and loses 40 with probability 0.4. Find expected value.', 'The expected value is 44.', 'The gain contributes 60 to expected value and the loss contributes negative 16. Their probability-weighted sum is 44, which is a long-run average rather than a guaranteed outcome.', 'Expected value = 0.6 x 100 + 0.4 x (-40)'],
  ['Medium', 'What does variance measure?', 'The average squared distance from the mean.', 'It measures dispersion but is expressed in squared units.', 'Variance = Average of squared deviations'],
  ['Medium', 'A portfolio invests 60% at 8% and 40% at 12%. Find expected return.', 'The portfolio’s expected return is 9.6%.', 'The two return contributions are 4.8% and 4.8%. Add the weighted contributions; do not take a simple 10% average because the allocations differ.', 'Expected return = 0.60 x 8% + 0.40 x 12%'],
  ['Medium', 'A return is 1.5 standard deviations above the mean. What does that indicate?', 'Its z-score is 1.5: the return is 1.5 standard deviations above the mean.', 'Whether that is unusual depends on the distribution and the threshold being used; the z-score alone does not establish an outlier.', 'z = (Observation - Mean) / Standard deviation = 1.5'],
  ['Medium', 'Group A has 20 observations with an average of 50. Group B has 30 observations with an average of 60. Find the combined average.', '56.', 'Combine the group totals, not their two averages: (20 x 50 + 30 x 60)/50 = 56.', 'Combined mean = (n1m1 + n2m2)/(n1 + n2)'],
  ['Medium', 'Which is more robust to an extreme outlier: mean or median?', 'The median is more robust.', 'An extreme value directly changes the arithmetic total and therefore the mean. It usually has much less effect on the middle-ranked observation, making the median preferable for strongly skewed data.', 'Median = Middle ranked value; Mean = Sum / Count'],
  ['Medium', 'How do you calculate a weighted average for grouped data?', 'Multiply each value by its weight, sum, and divide by total weight.', 'This prevents small and large groups from receiving equal influence.', 'Weighted mean = Sum(value x weight) / Sum(weights)'],
  ['Medium', 'What does coefficient of variation compare?', 'Relative dispersion across data sets with different means or units.', 'It is standard deviation divided by the mean.', 'CV = Standard deviation / Mean'],
  ['Medium', 'What is the z-score of 70 when mean is 50 and standard deviation is 10?', 'The z-score is 2.', 'The observation exceeds the mean by 20. Dividing that distance by the 10-unit standard deviation places it exactly two standard deviations above the mean.', 'z = (70 - 50) / 10'],
  ['Medium', 'What does it mean when an observation is at the 90th percentile?', 'Approximately 90% of observations are at or below it, and approximately 10% are above it.', 'Percentiles describe relative position after the observations are ordered.', '90th percentile = Value with about 90% of observations at or below it'],
  ['Hard', 'What does the slope of a regression line represent?', 'The expected change in the dependent variable for a one-unit change in the independent variable.', 'It is a conditional association, not automatically causation.', 'Slope = Covariance(X,Y) / Variance(X)'],
  ['Medium', 'What is the null hypothesis in a test of whether a campaign changed default rates?', 'That the campaign did not change the default rate.', 'The alternative states that a change exists.', 'H0: No change; H1: Change exists'],
  ['Medium', 'How should a 95% confidence level be interpreted?', 'The method captures the true parameter in 95% of repeated samples in the long run.', 'It is not the probability that one fixed parameter is random.', 'Confidence level = 1 - Significance level'],
  ['Medium', 'What is the expected value of a fair six-sided die roll?', '3.5.', 'Average the six equally likely outcomes from 1 through 6.', 'Expected value = (1 + 2 + 3 + 4 + 5 + 6) / 6'],
]);

const logicalReasoning = topic('logic', 'Logical Reasoning and Puzzles', [
  ['Medium', 'Complete the sequence: 2, 6, 12, 20, 30, ?', '42.', 'The terms are n(n + 1): 1x2, 2x3, 3x4, 4x5, 5x6, so the next is 6x7.', 'Next term = 6 x 7 = 42'],
  ['Medium', 'Complete the interleaved sequence: 3, 8, 5, 12, 7, 16, 9, ?', '20.', 'Odd positions are 3, 5, 7, 9; even positions are 8, 12, 16, 20.', 'Separate odd and even positions'],
  ['Medium', 'In a code, alternate letters move forward by 1 and 2 positions. Using this rule, how is MARKET coded?', 'MARKET is coded as NCSMFV.', 'Apply the shifts in order: M+1=N, A+2=C, R+1=S, K+2=M, E+1=F, and T+2=V. The alternating rule must restart at the first letter of the word.', 'Apply shifts +1, +2, +1, +2, +1, +2'],
  ['Medium', 'Five people A, B, C, D, and E sit in a row. C is in the middle, A sits immediately left of C, E is at the right end, and D sits immediately left of E. Who is at the left end?', 'B is at the left end.', 'C fixes position three and A therefore takes position two. E fixes position five and D takes position four, leaving only position one for B.', 'Forced arrangement = B-A-C-D-E'],
  ['Hard', 'Six distinct people sit around a circular table. If A and B must sit together, how many arrangements are possible?', '48.', 'Treat A and B as one block. Five units have (5 - 1)! circular arrangements, and A-B can be ordered in two ways.', 'Arrangements = 4! x 2 = 48'],
  ['Medium', 'Five candidates P, Q, R, S, and T are ranked. P is above Q but below T; R is below Q; and S is above T. Who ranks third?', 'P ranks third.', 'Combine the chains S above T, T above P, P above Q, and Q above R. They form one complete ranking with no unresolved position.', 'Forced order = S > T > P > Q > R'],
  ['Medium', 'All analysts are graduates; some graduates are coders. What follows?', 'Some analysts may be coders, but it is not guaranteed.', 'A subset relationship does not imply overlap with another subset.', 'Avoid reversing set inclusion'],
  ['Medium', 'A statement says all covenant breaches are defaults. What assumption must be tested?', 'Whether every breach actually triggers a default under the agreement.', 'A breach can be technical, waivable, or cured.', 'Separate necessary from sufficient conditions'],
  ['Medium', 'A, B, C, and D live on floors 1 through 4, one per floor. A lives above C, B lives immediately below A, and D lives on floor 1. Who lives on floor 4?', 'A.', 'D must be on 1. The only remaining consecutive placement with A above C is C on 2, B on 3, and A on 4.', 'Use a floor-position grid'],
  ['Medium', 'Pointing to a woman, Ravi says, "Her mother’s only son is my father." How is the woman related to Ravi?', 'She is Ravi’s paternal aunt.', 'The woman and Ravi’s father share the same mother, so she is his father’s sister.', 'Translate the relation from the innermost phrase outward'],
  ['Medium', 'Facing north, a person walks 10 km, turns right and walks 6 km, turns right and walks 10 km, then turns left and walks 4 km. Where is the person from the start?', '10 km east.', 'The north and south movements cancel. The two eastward movements total 10 km.', 'Track both direction and coordinates'],
  ['Medium', 'Which pair breaks the pattern: AZ, BY, CX, DW, EV, FV, GT?', 'FV.', 'In every valid pair, alphabet positions sum to 27. F and V sum to 28.', 'Pair rule: first position + second position = 27'],
  ['Medium', 'What is x? Statement I: x + y = 10. Statement II: x - y = 2. Are the statements sufficient?', 'Neither statement alone is sufficient; together they are sufficient and x = 6.', 'Each statement has two unknowns. Combining them eliminates y.', 'Add the equations: 2x = 12'],
  ['Medium', 'What is the angle between the hour and minute hands at 3:20?', 'The smaller angle is 20 degrees.', 'At 3:20 the minute hand is at 120 degrees and the continuously moving hour hand is at 100 degrees. Their absolute difference is therefore 20 degrees.', 'Angle = |30H - 5.5M| = |90 - 110| = 20 degrees'],
  ['Medium', 'How many odd days are in an ordinary year and a leap year?', 'One and two respectively.', '365 days leave one day after complete weeks; 366 leave two.', 'Ordinary year = 1 odd day; leap year = 2'],
  ['Hard', 'Two ropes each burn in 60 seconds at uneven rates. How can you measure 45 seconds?', 'Light one rope at both ends and the other at one end; then light the second end of the remaining rope.', 'The first rope finishes in 30 seconds; the remaining rope then takes 15 more seconds.', 'Uneven burn rates require lighting both ends'],
  ['Hard', 'Seven people numbered 1 to 7 stand in a circle. Starting with person 2, every second remaining person is eliminated. Who survives?', 'Person 7.', 'The elimination order is 2, 4, 6, 1, 5, 3, leaving 7.', 'Josephus recurrence for n = 7, k = 2 gives survivor 7'],
  ['Medium', 'Which assumption weakens an argument that higher revenue always means better performance?', 'Revenue may have grown with lower margins or worse cash collection.', 'A single KPI does not establish overall performance.', 'Test omitted variables'],
  ['Hard', 'What is the minimum number of adjacent swaps required to transform ABCD into DCBA?', '6.', 'The reversed order has six inversions: every pair is out of order. Each adjacent swap removes at most one inversion.', 'Minimum adjacent swaps = Number of inversions = 4 x 3 / 2'],
  ['Medium', 'All secured loans are reviewed, and some reviewed loans are delinquent. Can we conclude that some secured loans are delinquent?', 'No.', 'The delinquent reviewed loans need not belong to the secured-loan subset.', 'Shared membership in a larger set does not prove overlap'],
  ['Medium', 'Complete the letter series: A, C, F, J, O, ?', 'The missing letter is U.', 'The alphabet-position gaps increase consecutively: A to C is +2, then +3, +4, and +5. The next +6 jump moves O to U.', 'Alphabet positions: 1, 3, 6, 10, 15, 21'],
  ['Hard', 'Complete the letter series: Z, W, S, N, H, ?', 'The missing letter is A.', 'The backward jumps increase in size: -3, -4, -5, and -6. Applying the next -7 jump to H reaches A without requiring alphabet wraparound.', 'Alphabet positions: 26, 23, 19, 14, 8, 1'],
  ['Medium', 'Complete the word pattern: ACE, BDF, CEG, ?', 'DFH.', 'Each new group moves every letter one place forward.', 'ACE + 1 letter at each position = BDF, then CEG, then DFH'],
  ['Medium', 'If a word’s value is the sum of its letters’ alphabet positions, what is the value of CREDIT?', '59.', 'C=3, R=18, E=5, D=4, I=9, and T=20; the total is 59.', '3 + 18 + 5 + 4 + 9 + 20 = 59'],
  ['Hard', 'Which word cannot be formed from the letters of SECURITIZATION: REACTION, NOTICE, TRACTION, or CUSTOMER?', 'CUSTOMER.', 'CUSTOMER requires the letter M, which does not appear in SECURITIZATION. The other three words use only available letters and counts.', 'Check both letter presence and repeated-letter counts'],
  ['Hard', 'Using the reverse-alphabet code A↔Z, B↔Y, and so on, how is FINANCE coded?', 'FINANCE is coded as URMZMXV.', 'Pair each letter with the one whose alphabet position sums to 27: F→U, I→R, N→M, A→Z, N→M, C→X, and E→V.', 'Coded position = 27 - Original alphabet position'],
  ['Medium', 'Arrange the letters of CREDIT alphabetically. Which two letters occupy the middle positions?', 'E and I.', 'The order is C, D, E, I, R, T, so positions three and four are E and I.', 'Sort letters before selecting positions'],
  ['Medium', 'Which word is the odd one out: Audit, Verify, Reconcile, Estimate?', 'Estimate.', 'Audit, verify, and reconcile test or validate information; estimate creates an approximate value.', 'Classify words by function, not spelling'],
]);

const dataVerbal = topic('data', 'Data Interpretation and Verbal Ability', [
  ['Medium', 'Revenue rises from 800 to 920 in year one and to 1,058 in year two. What is the two-year CAGR?', '15%.', 'The total multiplier is 1,058/800 = 1.3225, whose square root is 1.15.', 'CAGR = (1,058 / 800)^(1/2) - 1 = 15%'],
  ['Hard', 'Revenue rises from 100 to 120, EBITDA from 20 to 21, and debt from 40 to 63. Which leverage metric deteriorates, and by how much?', 'Debt/EBITDA deteriorates from 2.0x to 3.0x, an increase of 1.0x.', 'Revenue grew 20%, but EBITDA grew only 5% while debt rose 57.5%. The borrower therefore has materially more debt per unit of operating earnings.', 'Debt/EBITDA: 40/20 = 2.0x; 63/21 = 3.0x'],
  ['Hard', 'A lender records 20 defaults from 1,000 originated loans in year one and 30 defaults from 2,000 loans in year two. Did credit performance improve or deteriorate on this evidence?', 'The observed default rate improved from 2.0% to 1.5%, a decline of 0.5 percentage points, even though the number of defaults increased.', 'Absolute defaults rose because the originated population doubled. The rate is the relevant first comparison, although a full conclusion would still control for vintage and seasoning.', 'Year 1 = 20/1,000 = 2.0%; Year 2 = 30/2,000 = 1.5%'],
  ['Hard', 'A fixed-rate bond portfolio has modified duration of 4.5. If market yields rise by 80 basis points, estimate the portfolio’s percentage price change before convexity.', 'The estimated price change is a 3.6% decline.', 'Modified duration converts a small yield movement into an approximate price movement. The negative sign reflects the inverse relationship between fixed-rate bond prices and yields.', 'Percentage price change ≈ -4.5 x 0.008 = -3.6%'],
  ['Hard', 'A portfolio is 40% corporate credit with a 2% default rate, 35% consumer with a 4% rate, and 25% real estate with a 3% rate. What is the portfolio’s expected default rate?', '2.95%.', 'Weight each segment default rate by its portfolio share: 0.40x2% + 0.35x4% + 0.25x3%.', 'Expected default rate = 0.8% + 1.4% + 0.75% = 2.95%'],
  ['Hard', 'A portfolio has exposures of 100 at 1% default probability, 300 at 4%, and 600 at 2%. Calculate expected defaulted exposure and the exposure-weighted default rate.', 'Expected defaulted exposure is 25, and the weighted default rate is 2.5%.', 'The segment contributions are 1, 12, and 12. Adding probabilities without weighting would ignore the very different exposure sizes.', 'Expected default = 100x1% + 300x4% + 600x2% = 25; Rate = 25/1,000 = 2.5%'],
  ['Hard', 'A 1,500 loan portfolio has 600 of corporate exposure with 24 non-performing, 450 of consumer exposure with 27 non-performing, and the rest in real estate. If the overall non-performing ratio is 5%, find real-estate exposure and its non-performing amount.', 'Real-estate exposure is 450, of which 24 is non-performing.', 'Total non-performing exposure is 1,500x5% = 75. Real estate is 1,500 - 600 - 450 = 450, and its non-performing amount is 75 - 24 - 27 = 24.', 'Real estate = 1,500 - 600 - 450; Real-estate NPL = 1,500x5% - 24 - 27'],
  ['Medium', 'A portfolio grows from 100 to 133.1 over three years. What is its CAGR?', 'The three-year CAGR is 10%.', 'The total growth multiple is 1.331. Taking its cube root gives 1.10, meaning the same compounded 10% annual rate would produce the observed ending value.', 'CAGR = (133.1 / 100)^(1/3) - 1 = 10%'],
  ['Medium', 'A portfolio falls from 100 loans with an average balance of 10 to 80 loans with an average balance of 12. Did total exposure rise or fall?', 'Total exposure fell from 1,000 to 960, a decline of 4%.', 'The 20% decline in loan count more than offsets the 20% rise in average balance. An average cannot determine the portfolio total without the corresponding count.', 'Exposure = Count x Average balance; Change = (960/1,000) - 1 = -4%'],
  ['Hard', 'Report A shows 1,000 loans but includes 25 duplicate records. Report B shows 980 loans but excludes five valid pending records. After those adjustments, what unresolved difference remains?', 'Report A has 975 unique loans and adjusted Report B has 985 loans, leaving an unresolved difference of 10 loans.', 'The reconciliation should not force the totals to agree. It should document the known population adjustments and isolate the residual ten records for key-level investigation.', 'A adjusted = 1,000 - 25 = 975; B adjusted = 980 + 5 = 985; Difference = 10'],
  ['Medium', 'Choose the correct sentence: "Neither the analyst nor the reviewers was/were satisfied with the reconciliation."', '"Neither the analyst nor the reviewers were satisfied with the reconciliation."', 'With neither...nor, the verb normally agrees with the nearer subject; reviewers is plural.', 'Match the verb to the nearer subject'],
  ['Medium', 'Choose the correct sentence: "Each of the projections, together with its assumptions, is/are reviewed."', '"Each of the projections, together with its assumptions, is reviewed."', 'The subject is each, which is singular; the intervening phrase does not change it.', 'Each takes a singular verb'],
  ['Medium', 'Which phrase is most professional: “Please revert back” or “Please respond”?', '“Please respond” is the clearer phrase.', 'In standard business English, respond already conveys the requested action, while revert back is redundant and can be ambiguous outside Indian corporate usage.', 'Prefer a direct verb that names the required action'],
  ['Medium', 'Read this note: "Thirty-day delinquencies rose from 2.0% to 3.4%. Management responded by lowering maximum LTV and requiring stronger income verification." What is the strongest one-sentence summary?', 'Early arrears worsened, prompting management to tighten collateral and affordability standards.', 'The summary preserves the observed deterioration and the management response without claiming that the new policy has already improved performance.', 'Summary = Observed credit change + documented response'],
  ['Hard', 'Delinquency rises from 2% to 4% in a segment after a policy change, while a comparable control segment rises from 2% to 2.5%. What is the difference-in-differences estimate?', 'The policy segment’s relative deterioration is 1.5 percentage points.', 'The treated segment worsened by 2.0 points while the control worsened by 0.5 points. Subtracting the common movement isolates a 1.5-point relative change, subject to the parallel-trends assumption.', 'Difference-in-differences = (4% - 2%) - (2.5% - 2%) = 1.5 percentage points'],
  ['Medium', 'Arrange these reporting steps in logical order: A) Import the raw file. B) Review exceptions. C) Standardize the fields. D) Release the report.', 'A, C, B, D.', 'The data must be imported before it is standardized, exceptions are reviewed after processing, and release comes last.', 'Order steps by operational dependency'],
  ['Medium', 'Choose the grammatically correct sentence: "The portfolio has fewer loans and less exposure" or "The portfolio has less loans and fewer exposure."', '"The portfolio has fewer loans and less exposure" is correct.', 'Use fewer for countable items such as loans and less for an uncountable quantity such as total exposure.', 'Fewer + countable plural; Less + uncountable amount'],
  ['Medium', 'A source file shows EBITDA of 84, while the model reports 81 after an unexplained hardcode. Which review comment is strongest?', '"The model EBITDA is 3 below the source because the formula contains an unexplained hardcode; replace it with the validated source link."', 'The comment identifies the observable discrepancy, quantifies it, names the cause, and gives a corrective action. Calling the model "wrong" alone is not reviewable evidence.', 'Finding = Evidence + quantified difference + root cause + action'],
  ['Medium', 'Rewrite this sentence without redundant causation: "Due to the fact that collections were delayed, therefore liquidity declined."', '"Because collections were delayed, liquidity declined."', 'Use one causal connector, not both "due to the fact that" and "therefore." The revision is shorter while preserving the causal meaning.', 'Prefer one precise connector: Because X, Y'],
  ['Medium', 'Summarize this update in one sentence: "The central bank raised its policy rate by 25 basis points. Bank funding costs rose, but the effect on loan demand remains uncertain."', 'A 25-basis-point policy-rate increase raised bank funding costs, while its effect on loan demand remains uncertain.', 'The summary retains the event, the observed transmission effect, and the unresolved consequence without adding a prediction.', 'Summary = Event + observed impact + material uncertainty'],
]);

const excel = topic('excel', 'Excel and Spreadsheet Assessment', [
  ['Easy', 'How would you use IF to flag a DSCR below 1.20x?', 'Use an IF test returning “Breach” when DSCR < 1.20.', 'The formula converts a threshold into a visible exception.', '=IF(DSCR<1.2,"Breach","Pass")'],
  ['Easy', 'How would you total exposure for one asset class using SUMIFS?', 'Use the exposure column as the sum range and the asset-class column with "Corporate" as the criterion.', 'SUMIFS evaluates every row against the criterion and adds only matching exposure values. Lock or structure the ranges so copied formulas do not drift.', '=SUMIFS(exposure,asset_class,"Corporate")'],
  ['Medium', 'How can SUMPRODUCT calculate a weighted portfolio return?', 'Pass the aligned weight and return ranges to SUMPRODUCT so each row’s contribution is multiplied and then summed.', 'The weights and returns must cover identical rows, and the weights should reconcile to 100%. A simple average is wrong when allocations differ.', '=SUMPRODUCT(weights,returns)'],
  ['Easy', 'What does VLOOKUP do?', 'It searches the first column of a table and returns a value from a selected column.', 'It is useful for exact-match lookups but is directionally limited.', '=VLOOKUP(key,table,column,FALSE)'],
  ['Medium', 'What is a limitation of VLOOKUP?', 'The lookup column must be the first column and inserted columns can change the index.', 'INDEX/MATCH or XLOOKUP is often more robust.', 'Prefer exact match and controlled ranges'],
  ['Medium', 'Why might XLOOKUP be preferable to VLOOKUP?', 'It can look left or right, defaults to exact match, and supports not-found handling.', 'It reduces common lookup errors.', '=XLOOKUP(key,lookup_array,return_array,"Not found")'],
  ['Medium', 'How does INDEX/MATCH provide a flexible lookup?', 'MATCH finds the position and INDEX returns the corresponding value.', 'It does not depend on a hard-coded column number.', '=INDEX(return_range,MATCH(key,lookup_range,0))'],
  ['Easy', 'What is the difference between A1, $A$1, A$1, and $A1?', 'They represent relative, absolute, row-locked, and column-locked references.', 'Reference type controls how formulas behave when copied.', 'Use $ to lock rows or columns'],
  ['Easy', 'What does pressing F4 while editing a reference do?', 'It cycles through relative and absolute reference forms.', 'This is a fast way to lock an input cell.', 'F4 cycles A1 -> $A$1 -> A$1 -> $A1'],
  ['Medium', 'How would you build a PivotTable by asset class and rating?', 'Put asset class and rating in row fields and exposure in values.', 'PivotTables summarize large datasets without changing the source.', 'Rows = dimensions; Values = aggregation'],
  ['Easy', 'How would you filter a report to show only overdue loans?', 'Apply a date or status filter to the relevant column.', 'Filtering changes the view, not the underlying data.', 'Use AutoFilter with a clear criterion'],
  ['Medium', 'How would you identify duplicate loan IDs?', 'Count each ID across the full ID range and flag any result greater than one; conditional formatting can apply the same test visually.', 'A duplicate-ID check should distinguish true duplicate records from legitimate repeated observations across different as-of dates.', '=COUNTIF(id_range,id)>1'],
  ['Easy', 'How would conditional formatting flag a covenant breach?', 'Apply a rule when the metric is below or above its contractual threshold.', 'Visual flags help reviewers focus on exceptions.', 'Rule = Metric compared with Threshold'],
  ['Easy', 'How would data validation restrict a status field?', 'Create a list validation rule linked to the approved status values and reject entries outside that list.', 'The controlled list prevents spelling variants from breaking filters, mappings, and summary formulas. Keep the source list governed and easy to update.', 'Validation list = Approved values'],
  ['Medium', 'Why use IFERROR around a lookup?', 'To return a controlled message or blank when the lookup fails.', 'It prevents raw error codes from contaminating reports.', '=IFERROR(lookup,"Missing")'],
  ['Medium', 'What is OFFSET used for, and what is a risk?', 'OFFSET returns a reference shifted from a starting cell with optional height and width, but it is volatile and can slow a large workbook.', 'Use it only when a dynamic range genuinely requires positional movement. Structured references or INDEX often provide a more transparent and efficient model.', 'OFFSET(reference,rows,cols,height,width)'],
  ['Medium', 'What does INDIRECT do?', 'INDIRECT converts text such as a sheet-and-cell address into a live Excel reference.', 'It is volatile, is difficult to audit, and does not update safely when referenced workbooks or structures change. Prefer direct references where practical.', '=INDIRECT("B"&A1)'],
  ['Medium', 'How would you reconcile two portfolio reports?', 'Align keys and dates, compare values, isolate differences, and document adjustments.', 'A reconciliation needs scope control before formula work.', 'Difference = Report A - Report B'],
  ['Hard', 'How would you trace a wrong output in a financial model?', 'Check inputs, precedents, formulas, units, and intermediate totals.', 'Trace from output backward through the calculation chain.', 'Output -> formula -> precedent -> source'],
  ['Hard', 'How would you build a sensitivity table for DSCR?', 'Separate inputs, vary the selected assumptions, and observe the output under each scenario.', 'Scenario analysis makes model risk visible.', 'Output = f(Operating cash flow, Interest, Principal)'],
]);

const finance = topic('finance', 'Finance and Accounting Fundamentals', [
  ['Easy', 'Explain time value of money to a beginner.', 'A rupee today can earn a return, so it is worth more than a rupee received later.', 'Discounting converts future cash flows into today’s value.', 'PV = FV / (1 + r)^n'],
  ['Easy', 'What is the present value of 121 received in two years at 10%?', 'The present value is 100.', 'Discount each year’s required return: 121 divided by 1.10 gives 110 after one year, and dividing by 1.10 again gives 100 today.', 'PV = 121 / 1.10^2 = 100'],
  ['Easy', 'What is the future value of 1,000 invested at 8% for two years?', 'The future value is 1,166.40.', 'The first year grows the investment to 1,080. The second year earns 8% on both the original principal and first-year interest, producing 1,166.40.', 'FV = 1,000 x 1.08^2 = 1,166.40'],
  ['Medium', 'What is the present value of a three-year annuity of 100 at 10%?', 'Approximately 248.69.', 'Discount each annual payment and add the values.', 'PV annuity = PMT x [1 - 1/(1+r)^n] / r'],
  ['Medium', 'How do you calculate NPV?', 'Discount future cash inflows and outflows and subtract the initial investment.', 'A positive NPV means value is created at the selected discount rate.', 'NPV = Sum[CF_t/(1+r)^t] - Initial investment'],
  ['Hard', 'Why can NPV and IRR rank mutually exclusive projects differently?', 'NPV uses absolute value at a discount rate; IRR uses a percentage return and can be affected by scale and timing.', 'Use incremental cash flows or NPV when rankings conflict.', 'IRR solves NPV = 0'],
  ['Hard', 'How is WACC calculated?', 'As the market-value-weighted after-tax cost of debt and cost of equity.', 'Use the target capital structure and consistent market inputs.', 'WACC = E/V x Ke + D/V x Kd x (1-T)'],
  ['Medium', 'How do cost of debt and cost of equity differ?', 'Debt has contractual claims and tax deductibility; equity is residual and usually carries higher risk.', 'The required return reflects claim priority and risk.', 'After-tax debt cost = Kd x (1-T)'],
  ['Medium', 'What are the main steps in a DCF model?', 'Forecast cash flows, estimate terminal value, discount them, and bridge enterprise value to equity value.', 'The assumptions drive the result more than the spreadsheet format.', 'EV = PV of forecast FCF + PV of terminal value'],
  ['Hard', 'How should terminal growth be selected?', 'It should be sustainable, below the discount rate, and consistent with long-run economics.', 'An aggressive terminal growth rate can dominate the valuation.', 'Terminal value = FCF_(n+1) / (WACC - g)'],
  ['Easy', 'What do the income statement, balance sheet, and cash-flow statement show?', 'Profit over a period, financial position at a date, and cash movements over a period.', 'Together they explain earnings, resources, obligations, and liquidity.', 'Assets = Liabilities + Equity'],
  ['Medium', 'How does an increase in receivables affect cash flow?', 'It usually reduces operating cash flow relative to accrual profit.', 'Revenue may be recorded before cash is collected.', 'CFO adjustment for AR increase = -Increase in AR'],
  ['Easy', 'Current assets are 900 and current liabilities are 600. What is the current ratio?', 'The current ratio is 1.5x.', 'The company reports 1.50 of current assets for each 1.00 of current liabilities. This indicates balance-sheet coverage, not whether those assets will convert to cash on time.', 'Current ratio = 900 / 600 = 1.5x'],
  ['Easy', 'What does ROA measure?', 'Profit generated per unit of assets.', 'Compare the numerator and asset base consistently.', 'ROA = Net income / Average assets'],
  ['Medium', 'What is debt-to-equity ratio?', 'Debt relative to shareholders’ equity.', 'It indicates financial leverage but must be compared across similar industries.', 'D/E = Debt / Equity'],
  ['Medium', 'Is a high debt ratio always bad?', 'No. It can be efficient in stable cash-flow businesses but increases refinancing and default risk.', 'Interpret leverage with cash flow, covenants, and industry economics.', 'Risk rises when fixed claims exceed resilient cash flow'],
  ['Easy', 'An asset costs 260, has residual value 20, and a six-year life. What is annual straight-line depreciation?', 'Annual straight-line depreciation is 40.', 'Only the 240 depreciable base is allocated because the 20 residual value is expected to remain. Straight-line treatment spreads that base evenly across six years.', 'Depreciation = (260 - 20) / 6 = 40'],
  ['Medium', 'What happens when a borrower prepays a loan?', 'Principal outstanding falls and future interest expense falls, subject to any prepayment premium.', 'Separate principal repayment from interest and fees.', 'Ending principal = Beginning principal - Prepayment'],
  ['Medium', 'What is a call premium?', 'An amount above par paid when a callable bond or loan is redeemed early.', 'It compensates the investor or lender for early repayment.', 'Call price = Par value + Premium'],
  ['Medium', 'What is a call discount?', 'A redemption price below par under the stated terms.', 'The exact treatment depends on the instrument agreement.', 'Call price = Par value - Discount'],
  ['Easy', 'What happens to a bond’s price when market interest rates rise?', 'Its price generally falls, all else equal.', 'Existing coupons become less attractive relative to new market yields.', 'Price and yield generally move inversely'],
  ['Medium', 'What is bond yield?', 'The return implied by the bond’s price and expected cash flows.', 'Coupon rate and yield can differ when price is not par.', 'Yield reflects discounted coupons and principal'],
  ['Hard', 'What does duration measure?', 'Approximate sensitivity of a bond price to a change in yield.', 'Longer duration generally means greater interest-rate sensitivity.', 'Duration = Weighted average timing of cash flows'],
  ['Hard', 'What is modified duration used for?', 'To estimate percentage price change for a small yield change.', 'It adjusts Macaulay duration for the yield convention.', 'Percentage price change ≈ -Modified duration x Yield change'],
  ['Medium', 'What are repo rate and reverse repo rate?', 'Repo is the rate at which the central bank lends against securities; reverse repo is the rate at which it absorbs funds.', 'They are monetary-policy tools affecting liquidity and short-term rates.', 'Policy transmission works through funding liquidity'],
  ['Medium', 'Why did markets move from LIBOR toward SOFR?', 'LIBOR relied on panel estimates while SOFR is based on transactions in secured overnight funding.', 'Benchmark choice affects floating-rate contracts and fallback language.', 'Floating rate = Benchmark + Spread'],
  ['Medium', 'How can portfolio return be calculated?', 'Weight each asset’s return by its portfolio allocation and add.', 'The portfolio return is not generally the simple average of asset returns.', 'Rp = Sum(weight_i x return_i)'],
]);

const creditMarkets = topic('credit', 'Credit, Markets and Securitization', [
  ['Easy', 'What does DSCR measure?', 'Whether cash flow covers scheduled debt service.', 'A ratio below 1.0x indicates insufficient modeled cash flow for the stated debt service.', 'DSCR = Cash flow available for debt service / Debt service'],
  ['Medium', 'Cash available for debt service is 210, interest is 60, and principal is 90. What is DSCR?', 'DSCR is 1.4x.', 'Scheduled debt service totals 150. Cash available therefore covers the obligation 1.4 times, leaving a 60 cushion before considering definition differences or future stress.', 'DSCR = 210 / (60 + 90) = 1.4x'],
  ['Easy', 'What does LTV measure?', 'Loan amount relative to collateral value.', 'Higher LTV generally means less collateral protection.', 'LTV = Loan amount / Collateral value'],
  ['Medium', 'A property is worth 1,000 and the loan is 650. What is LTV?', 'The loan-to-value ratio is 65%.', 'The lender has advanced 650 against 1,000 of stated collateral value, leaving a 35% value cushion before costs. LTV does not measure cash-flow repayment capacity.', 'LTV = 650 / 1,000 = 65%'],
  ['Medium', 'What is a leverage ratio?', 'A measure of debt relative to earnings, assets, or equity.', 'Always state the numerator, denominator, and whether debt is gross or net.', 'Example: Debt / EBITDA'],
  ['Medium', 'What do credit-rating agencies assess?', 'Relative creditworthiness and default risk of issuers or instruments.', 'Ratings are opinions, not guarantees of repayment.', 'Rating reflects assessed default risk'],
  ['Medium', 'How would you assess a borrower’s creditworthiness?', 'Review cash flow, leverage, coverage, liquidity, collateral, management, industry, and repayment history.', 'Use both quantitative and qualitative evidence.', 'Credit view = Capacity + Collateral + Conditions + Character'],
  ['Hard', 'What should happen after a borrower’s credit quality deteriorates?', 'Recheck data, update risk metrics, test covenants, stress cash flow, and escalate material changes.', 'The response should be evidence-led and tied to the agreement.', 'Monitor -> Validate -> Stress -> Escalate'],
  ['Easy', 'What is securitization?', 'Pooling financial assets and issuing securities backed by their cash flows.', 'It transforms granular receivables or loans into investable securities.', 'Assets -> SPV -> Notes -> Investors'],
  ['Easy', 'What is the role of an SPV in securitization?', 'To hold the pooled assets and issue securities, helping isolate the assets from the originator.', 'The legal structure and true-sale analysis matter.', 'SPV owns collateral and passes through cash flows'],
  ['Medium', 'What is asset-backed lending?', 'Lending secured by identifiable assets or receivables.', 'The lender monitors both borrower credit and collateral performance.', 'Advance rate = Loan / Eligible collateral'],
  ['Medium', 'What is loan servicing?', 'Administering payments, balances, notices, borrower data, and reporting for a loan or facility.', 'Servicing quality affects data integrity and collections.', 'Servicing = Administer + Collect + Reconcile + Report'],
  ['Medium', 'What is the difference between a whole loan and an ABS?', 'A whole loan is held as an individual loan exposure; ABS distributes pooled-asset cash flows through a structured security.', 'Reporting granularity and waterfall mechanics differ.', 'Whole loan = Asset-level; ABS = Pool-level structure'],
  ['Medium', 'What are CDOs and CLOs?', 'Structured securities backed by pools of debt; CLOs are commonly backed by leveraged loans.', 'Tranching allocates cash flow and loss risk differently across investors.', 'Senior to junior tranches absorb losses in order'],
  ['Medium', 'What is the difference between RMBS and CMBS?', 'RMBS is backed by residential mortgages; CMBS is backed by commercial real estate loans.', 'Collateral type drives underwriting and monitoring metrics.', 'Residential collateral vs commercial collateral'],
  ['Hard', 'What is a securitization cash-flow waterfall?', 'A priority order that allocates collections to fees, senior claims, subordinate claims, and residual holders.', 'Waterfalls determine who receives cash first and who absorbs shortfalls.', 'Priority of payments controls distributions'],
  ['Medium', 'What is an OC test?', 'An overcollateralization test comparing collateral support with note obligations.', 'A breach may redirect cash toward senior notes.', 'OC ratio = Collateral balance / Note balance'],
  ['Medium', 'What is an IC test?', 'An interest-coverage test comparing available cash flow with interest obligations.', 'A breach may trigger cash trapping or other protections.', 'IC ratio = Available interest cash / Interest due'],
  ['Medium', 'What is a concentration limit?', 'A cap on exposure to a borrower, sector, geography, vintage, or asset type.', 'Concentration limits reduce dependence on one risk source.', 'Concentration = Exposure to segment / Total exposure'],
  ['Medium', 'How are delinquency and default rates different?', 'Delinquency measures overdue payments; default is a more serious contractual or defined credit event.', 'Definitions and aging buckets must be consistent.', 'Rate = Relevant loans / Relevant population'],
  ['Hard', 'What is a borrowing base?', 'The eligible collateral value against which a facility can borrow.', 'Eligibility haircuts, advance rates, and concentration limits can reduce availability.', 'Borrowing base = Eligible collateral x Advance rates'],
]);

const marketAwareness = topic('markets', 'Market Awareness and Financial GK', [
  ['Medium', 'Two companies have index weights of 60% and 40%. Their shares return 10% and -5% respectively. What is the index return?', 'The index return is 4%.', 'A market index follows its stated weighting methodology, not a simple average of constituent returns. The larger positive constituent contributes 6%, while the smaller negative constituent contributes -2%.', 'Index return = 60%x10% + 40%x(-5%) = 4%'],
  ['Medium', 'A portfolio returns 7.2% while its Nifty 50 benchmark returns 8.0% over the same period. How should relative performance be stated?', 'The portfolio underperformed its benchmark by 0.8 percentage points.', 'Use the same dates, currency, and total-return convention before comparing. A raw return of 7.2% is positive, but it is weaker than the selected benchmark over that period.', 'Relative performance = 7.2% - 8.0% = -0.8 percentage points'],
  ['Medium', 'Two sources report index closes of 24,800 and 24,920. What must be reconciled before either figure is used in an assessment answer?', 'Reconcile the index, trading date, timestamp, close convention, currency, and whether either figure is delayed or adjusted.', 'Market levels are as-of facts. Selecting the number that looks plausible without aligning definitions can turn two valid observations into a false discrepancy.', 'Reliable market fact = Named index + exact as-of time + consistent close definition + primary source'],
  ['Medium', 'A company has 50 million shares at 120 per share, debt of 2,000 million, and cash of 500 million. Calculate market capitalization and enterprise value.', 'Market capitalization is 6,000 million and enterprise value is 7,500 million.', 'Market capitalization values only common equity. Enterprise value adds debt and subtracts excess cash to approximate the value attributable to all capital providers.', 'Market cap = 50m x 120 = 6,000m; EV = 6,000m + 2,000m - 500m = 7,500m'],
  ['Medium', 'What is an open-market operation?', 'A central bank purchase or sale of securities to influence liquidity and interest rates.', 'It works through the banking system and market liquidity.', 'Purchase adds liquidity; sale removes liquidity'],
  ['Medium', 'What generally happens when a central bank raises the repo rate?', 'Short-term funding becomes more expensive and demand may weaken.', 'The effect passes through borrowing costs, liquidity, and expectations.', 'Policy rate -> Funding cost -> Demand and valuations'],
  ['Medium', 'What generally happens when reverse-repo returns rise?', 'Banks may have more incentive to park funds with the central bank.', 'The precise effect depends on the operating framework.', 'Liquidity absorption affects money-market conditions'],
  ['Medium', 'How can inflation affect bond prices?', 'Higher expected inflation can raise yields and lower existing bond prices.', 'Real returns and policy expectations matter.', 'Higher yield -> Lower bond price'],
  ['Medium', 'What does an upward-sloping yield curve usually indicate?', 'Longer maturities yield more than shorter maturities.', 'Interpret the curve alongside inflation and growth expectations.', 'Yield curve = Yield by maturity'],
  ['Medium', 'A dollar loan pays compounded SOFR plus 250 basis points. If compounded SOFR for the period is 5.1%, what annualized contractual rate applies before fees?', 'The annualized contractual rate is 7.6%.', 'SOFR is the benchmark component and 250 basis points equals a 2.5% credit spread. The contract’s day-count, lookback, and compounding conventions still determine the exact cash interest.', 'Loan rate = 5.1% + 2.5% = 7.6%'],
  ['Medium', 'What was a central lesson from the 2008 financial crisis?', 'Leverage, weak underwriting, opaque securitization, and liquidity risk can amplify losses.', 'Risk can rise when models ignore correlated deterioration.', 'Systemic risk = Leverage + Correlation + Liquidity'],
  ['Medium', 'Why did the LIBOR manipulation episode create valuation and conduct risk for banks beyond regulatory fines?', 'A distorted benchmark could misprice loans, derivatives, and hedges while transferring value between counterparties and undermining contract integrity.', 'The core failure was reliance on judgment-based submissions with incentives and controls that permitted manipulation. Transaction-based benchmarks and stronger governance reduce, but do not eliminate, benchmark risk.', 'Benchmark risk = Weak evidence + conflicted submissions + broad contractual dependence'],
  ['Hard', 'An Indian exporter earns 30% of revenue in pounds while most costs are in rupees. If Brexit-related uncertainty weakens sterling by 8%, what is the first-order revenue translation impact before hedging?', 'Reported revenue falls by approximately 2.4%, assuming volumes and prices are unchanged.', 'Only the sterling-linked 30% of revenue is translated at the weaker rate. The actual earnings impact also depends on hedges, price changes, demand, and any sterling-denominated costs.', 'Translation impact ≈ 30% x -8% = -2.4%'],
  ['Hard', 'The European Union imposes a 10% tariff on a product that represents 20% of an Indian manufacturer’s sales. If the company absorbs the tariff entirely, what is the direct revenue-equivalent pressure before volume effects?', 'The direct pressure equals approximately 2% of total company sales.', 'The tariff applies only to the exposed EU product revenue. The eventual profit effect may be larger or smaller depending on gross margin, repricing, customer demand, and supply-chain changes.', 'Direct exposure = 20% of sales x 10% tariff = 2% of total sales'],
  ['Medium', 'Why can negative policy rates be used?', 'To encourage lending or investment by reducing the return on idle balances.', 'They can also create pressure on bank profitability and market behavior.', 'Policy rate below zero changes cash incentives'],
  ['Medium', 'Why does volatility often rise during financial downturns?', 'Uncertainty, deleveraging, liquidity stress, and changing expectations widen price movements.', 'Volatility is not the same as loss, but it signals instability.', 'Volatility = Dispersion of returns'],
  ['Medium', 'What is beta?', 'A measure of an asset’s sensitivity to movements in a benchmark.', 'Beta does not capture every form of risk.', 'Beta = Covariance(asset, market) / Variance(market)'],
  ['Medium', 'An asset manager has average AUM of 8,000 million and charges a 0.75% annual management fee. Estimate annual fee revenue before waivers and performance fees.', 'Estimated annual management-fee revenue is 60 million.', 'AUM is the managed asset base, not the manager’s own revenue or profit. Fee realization can differ because of tiered pricing, fee waivers, flows, and changing market values.', 'Fee revenue = 8,000m x 0.75% = 60m'],
  ['Medium', 'What sources should be used for current financial news?', 'Primary regulators, company filings, central banks, and reputable financial reporting.', 'Triangulate material facts and record the as-of date.', 'Source hierarchy = Primary evidence first'],
  ['Hard', 'A listed lender falls 9% after reporting higher profit but weaker collections and a rise in stage-three loans. How should the move be explained without overstating causation?', 'State that the shares fell 9% after the release and that weaker collections and higher impaired loans are plausible concerns despite profit growth; do not claim they caused the move without market evidence.', 'A credible explanation separates the observed price move and disclosed fundamentals from an inferred investor reaction. It should also check guidance, consensus expectations, volume, and concurrent market news.', 'Answer structure = Observed move + disclosed facts + plausible mechanism + competing explanations + uncertainty'],
]);

const newShortcuts = [
  shortcut(1, 'Percentage Multipliers', 'Use 1 + r/100 for an increase and 1 - r/100 for a decrease.', 'Example: +20% then -20% = 1.20 x 0.80 = 0.96, so the result is 4% lower. Use it whenever changes are sequential; each percentage applies to the updated base.'),
  shortcut(2, 'Ratio Scaling', 'If A:B = m:n and A+B is known, one part equals total/(m+n).', 'Example: 3:5 of 640 gives one part 80, so the shares are 240 and 400. Confirm that both parts use the same units.'),
  shortcut(3, 'Weighted Average', 'Weighted average = sum(value x weight) / sum(weights).', 'Example: 60 units at 80 and 40 at 110 gives (4,800 + 4,400)/100 = 92. Do not average the two prices unless the quantities are equal.'),
  shortcut(4, 'Average Replacement', 'New average = Old average + (New value - Replaced value)/Count.', 'Example: replacing 70 with 90 in five observations raises the average by 20/5 = 4. Use only when the observation count stays fixed.'),
  shortcut(5, 'Complementary Probability', 'P(at least one) = 1 - P(none).', 'For three fair coin tosses, P(at least one head) = 1 - (1/2)^3 = 7/8. It is usually faster than listing every successful outcome.'),
  shortcut(6, 'Expected Value', 'Expected value = sum(outcome x probability).', 'Example: a 60% chance of 100 and 40% chance of -50 gives 0.6 x 100 + 0.4 x (-50) = 40. Expected value is an average outcome, not a guarantee or a risk measure.'),
  shortcut(7, 'Speed Conversion', 'Multiply km/h by 5/18 to convert to m/s; multiply m/s by 18/5 to convert back.', '72 km/h becomes 72 x 5/18 = 20 m/s. Match the conversion to the distance and time units before calculating.'),
  shortcut(8, 'Work-Rate LCM', 'Choose a total-work LCM, convert each worker into units per day, and add the rates.', 'For 12-day and 18-day workers, total work 36 units gives rates 3 and 2, so joint time is 36/5 = 7.2 days. Use this for constant, independent work rates.'),
  shortcut(9, 'Standard-Deviation Reading', 'z = (observation - mean) / standard deviation.', 'If mean is 50, standard deviation is 5, and the observation is 60, z = 2. A z-score gives distance from the mean; it does not prove an observation is an outlier without context.'),
  shortcut(10, 'Excel Audit Chain', 'Trace output -> formula -> precedent -> source input.', 'This catches wrong references, units, hardcodes, and broken links faster than scanning the entire workbook. Add a check row and reconcile the output to an independent total.'),
  shortcut(11, 'Unit Digit Cycles', 'For powers, identify the repeating cycle of the last digit and reduce the exponent modulo the cycle length.', 'Powers of 7 end in 7, 9, 3, 1 repeatedly. Therefore 7^23 has the same unit digit as 7^3: 3. Use the cycle length, not the full exponent.'),
  shortcut(12, 'Equal-Distance Average Speed', 'For two equal distances at speeds a and b, average speed = 2ab/(a+b).', 'At 60 km/h out and 40 km/h back, average speed = 2 x 60 x 40 / 100 = 48 km/h. Do not use the arithmetic mean unless the times are equal.'),
  shortcut(13, 'Conditional Probability', 'P(A|B) = P(A and B) / P(B).', 'If 30 of 100 loans are both secured and delinquent, and 40 are delinquent, P(secured|delinquent) = 30/40 = 75%. State the conditioning event clearly.'),
  shortcut(14, 'Bayes Update', 'P(A|B) = P(B|A)P(A) / P(B).', 'If a test is positive, combine the test sensitivity with the base rate and false-positive rate before interpreting the result. A high accuracy claim alone is not enough.'),
  shortcut(15, 'Combinations and Permutations', 'nCr selects without order; nPr arranges with order. nCr = n!/[r!(n-r)!], nPr = n!/(n-r)!.', 'Choose two reviewers from ten: 10C2 = 45. Assign two distinct roles from ten people: 10P2 = 90. Decide whether order changes the outcome first.'),
  shortcut(16, 'Bond Price-Yield Direction', 'For a plain fixed-rate bond, price and yield move in opposite directions.', 'If market yield rises, the present value of the fixed coupons and principal falls. The relationship is not linear; longer duration generally means greater price sensitivity.'),
  shortcut(17, 'Discount-Factor Chain', 'Present value = future cash flow x discount factor; discount factors compound across periods.', 'At 10%, the two-year discount factor is 1/(1.10)^2 = 0.8264, so 100 received in two years is worth about 82.64 today. Keep rate and period units aligned.'),
  shortcut(18, 'Excel Navigation Shortcuts', 'Ctrl+Arrow jumps across a data region; Ctrl+Shift+Arrow selects it; Ctrl+PageUp/PageDown changes sheets.', 'Use Ctrl+Arrow to reach the edge of a loan tape and Ctrl+Shift+Arrow to select the data block before formatting or checking it. Blank cells can change where the shortcut stops.'),
  shortcut(19, 'Excel Review Shortcuts', 'Ctrl+1 opens Format Cells; F2 edits a formula; Ctrl+` shows formulas; Alt+= inserts AutoSum.', 'Use Ctrl+` to scan for hardcodes and broken patterns, F2 to inspect references, and Ctrl+1 to confirm units and formats. These are review tools, not substitutes for reconciliation.'),
  shortcut(20, 'Handshake as a Combination', 'The handshake count n(n-1)/2 is the same as choosing 2 people from n: nC2.', 'For 10 people, 10C2 = 45. The shortcut assumes each pair interacts once, so it also applies to unique pair comparisons, not repeated meetings.'),
];

